const GR_P8B=[
 ["Too much with すぎる","Verb stem or adjective stem + すぎる","すぎる (sugiru) after a verb stem or an adjective stem means “too much”. 食べる becomes 食べすぎる (eat too much). 高い becomes 高すぎる (too expensive): take off い first. For a な-adjective, use the stem: 便利すぎる (too convenient). いい becomes よすぎる and ない becomes なさすぎる. すぎる changes like a る-verb: すぎます, すぎました.",[["音","oto","sound"],["が","ga","(subject)"],["大きすぎます","ookisugimasu","is too loud"],["。","",""]],"The sound is too loud."],
 ["Easy and hard with やすい and にくい","Verb stem + やすい or にくい","やすい (yasui) after a verb stem means “easy to do”. にくい (nikui) means “hard to do”. 使う becomes 使いやすい (easy to use) and 使いにくい (hard to use). They change like い-adjectives: 使いやすいです, 使いやすかったです, 使いにくくないです.",[["この","kono","this"],["機械","kikai","machine"],["は","wa","(topic)"],["使いやすい","tsukaiyasui","easy to use"],["です","desu","is"],["。","",""]],"This machine is easy to use."],
 ["Ways of doing with 方","Verb stem + 方","方 (kata) after a verb stem means “way of doing”. 使う becomes 使い方 (way of using), 読む becomes 読み方 (way of reading), 作る becomes 作り方 (way of making). The whole word is a noun. The object particle を changes to の: 漢字を読む becomes 漢字の読み方.",[["漢字","kanji","kanji"],["の","no","of"],["読み方","yomikata","way of reading"],["を","o","(object)"],["教えて","oshiete","teach"],["ください","kudasai","please"],["。","",""]],"Please tell me how to read the kanji."],
 ["Purpose with ために","Dictionary form + ために, action","ために (tame ni) after the dictionary form of a verb says the purpose: “in order to …”. The part after ために is the action that you do for this purpose. Both parts have the same person as the subject. 見るために、行きます means “I go in order to see”. Use a verb that you do on purpose.",[["滝","taki","waterfall"],["を","o","(object)"],["見る","miru","see"],["ために","tame ni","in order to"],["山","yama","mountain"],["に","ni","to"],["行きます","ikimasu","go"],["。","",""]],"I go to the mountain in order to see the waterfall."],
 ["Right now with ところです","Dictionary form, ている form or た-form + ところです","ところです (tokoro desu) shows the stage of an action. The dictionary form + ところです means “am about to do”. The ている form + ところです means “am in the middle of doing”. The た-form + ところです means “have just done”. 今 (ima) is often added.",[["今","ima","now"],["、","",""],["ご飯","gohan","meal"],["を","o","(object)"],["食べている","tabete iru","am eating"],["ところです","tokoro desu","am in the middle of"],["。","",""]],"I am eating a meal right now."]
];
